import{_ as r,C as s,o as e,c as d,j as i,a as l,E as o,a3 as n}from"./chunks/framework.C6R8kWFE.js";const j=JSON.parse(`{"title":"8-dars (Mentor). Raqamli savodxonlik va raqamli madaniyat","description":"","frontmatter":{"title":"8-dars (Mentor). Raqamli savodxonlik va raqamli madaniyat","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"8-sinf (Foundation)","link":"/mentor/8-sinf-cs/"},"week":{"n":3,"link":"/mentor/8-sinf-cs/hafta-03/"},"g":8,"title":"Raqamli savodxonlik va raqamli madaniyat","lead":"Zamonaviy axborot olamida to'g'ri yo'l topish, tarmoq etiketi (Netiket), raqamli iz javobgarligi va feyk xabarlarni fosh qilish mahorati.","slide":"/slaydlar/8-sinf-cs/hafta-03/dars-2.html","test":"/slaydlar/8-sinf-cs/hafta-03/dars-2-test.html","student_link":"/8-sinf-cs/hafta-03/dars-2","tabs":[{"g":7,"link":"/mentor/8-sinf-cs/hafta-03/dars-1","current":false},{"g":8,"link":"/mentor/8-sinf-cs/hafta-03/dars-2","current":true},{"g":9,"link":"/mentor/8-sinf-cs/hafta-03/dars-3","current":false}],"prev":{"g":7,"title":"Klaviaturada tez va to‘g‘ri yozish ko‘nikmalari (Touch typing)","link":"/mentor/8-sinf-cs/hafta-03/dars-1"},"next":{"g":9,"title":"Raqamli transformatsiya tushunchasi","link":"/mentor/8-sinf-cs/hafta-03/dars-3"}}},"headers":[],"relativePath":"mentor/8-sinf-cs/hafta-03/dars-2.md","filePath":"mentor/8-sinf-cs/hafta-03/dars-2.md"}`),m={name:"mentor/8-sinf-cs/hafta-03/dars-2.md"},h={class:"blk"},g={id:"_1-dars-rejasi",tabindex:"-1"},q={class:"blk"},k={id:"_2-konspekt",tabindex:"-1"},u={class:"blk"},b={id:"_3-amaliy-topshiriqlar-va-yechimlari",tabindex:"-1"},y={class:"blk"},v={id:"_4-tezkor-nazorat-savollari-javoblari-bilan",tabindex:"-1"};function f(z,a,x,p,c,_){const t=s("Icon");return e(),d("div",null,[a[12]||(a[12]=i("p",null,[i("strong",null,"Hafta:"),l(" 3 · "),i("strong",null,"Davomiyligi:"),l(" 80 daqiqa · "),i("strong",null,"Turi:"),l(" nazariya + amaliy tahlil · "),i("strong",null,"II-bob"),l(", 8-dars")],-1)),i("div",h,[i("h2",g,[o(t,{name:"file-text"}),a[0]||(a[0]=l(" 1. Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars rejasi"'},"​",-1))]),a[2]||(a[2]=n('<p><strong>Maqsad:</strong> o&#39;quvchilarda zamonaviy raqamli jamiyatda yashash va ishlash ko&#39;nikmalari (raqamli savodxonlik), internetda muloqot odobi (Netiket / Netiquette), shaxsiy raqamli iz (Digital Footprint) va uning kelajakdagi oqibatlari, feyk va yolg&#39;on axborotlarni haqiqiy faktlardan ajratish (faktcheking) hamda raqamli vositalardan xavfsiz va unumli foydalanish madaniyatini shakllantirish.</p><p><strong>Kutiladigan natija:</strong></p><ul><li>Raqamli savodxonlikning 4 ta ustunini (axborot topish, tahlil qilish, yaratish va xavfsiz almashish) tushuntira oladi.</li><li>Netiket (tarmoq odobi) qoidalariga rioya qiladi (CapsLock bilan baqirmaslik, mualliflik huquqini hurmat qilish, kiberbullingga yo&#39;l qo&#39;ymaslik).</li><li>Faol va nofaol raqamli iz tushunchalarini farqlaydi, o&#39;z raqamli izini audit qila oladi.</li><li>Internetdagi feyk yangiliklar, klikbeyt sarlavhalar va soxta akkauntlarni aniqlashning 5 ta oltin qoidasini amalda qo&#39;llaydi.</li><li>Raqamli texnologiyalardan ta&#39;lim va o&#39;zini rivojlantirishda unumli foydalanish bo&#39;yicha shaxsiy strategiya tuza oladi.</li></ul><table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Mazmun</th></tr></thead><tbody><tr><td>0–10 daq</td><td>Takrorlash va kirish</td><td>7-dars (Touch typing). Muammoli keys: «Internetga bir marta yuklangan rasm yoki yozuvni butunlay o&#39;chirib yuborish mumkinmi?»</td></tr><tr><td>10–30 daq</td><td>Yangi mavzu: Nazariya</td><td>Raqamli savodxonlik, Netiket qoidalari, Raqamli iz anatomiyasi, Feyk axborotlarni fosh qilish</td></tr><tr><td>30–35 daq</td><td>Tanaffus</td><td>Harakatli tanaffus</td></tr><tr><td>35–65 daq</td><td>Amaliy mashg&#39;ulot</td><td>«O&#39;z raqamli izingizni tekshiring» qidiruv mashqi va feyk xabarlarni tahlil qilish keysi</td></tr><tr><td>65–75 daq</td><td>Tezkor nazorat</td><td>5 ta savol va vaziyatli test</td></tr><tr><td>75–80 daq</td><td>Xulosa va vazifa</td><td>Asosiy xulosalar va uyga vazifani berish</td></tr></tbody></table><hr>',5))]),i("div",q,[i("h2",k,[o(t,{name:"file-text"}),a[3]||(a[3]=l(" 2. Konspekt ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-konspekt","aria-label":'Permalink to "<Icon name="file-text" /> 2. Konspekt"'},"​",-1))]),a[5]||(a[5]=n('<h3 id="_2-1-raqamli-savodxonlik-nima" tabindex="-1">2.1. Raqamli savodxonlik nima? <a class="header-anchor" href="#_2-1-raqamli-savodxonlik-nima" aria-label="Permalink to &quot;2.1. Raqamli savodxonlik nima?&quot;">​</a></h3><p><strong>Raqamli savodxonlik (Digital Literacy)</strong> — bu zamonaviy raqamli texnologiyalar, kompyuterlar, smartfonlar va internetdan xavfsiz, samarali va tanqidiy foydalana olish ko&#39;nikmalari majmuasidir.</p><p>U faqat tugmalarni bosishni bilish emas, balki 4 ta asosiy komponentni o&#39;z ichiga oladi:</p><ol><li><strong>Axborot savodxonligi:</strong> Internetdan kerakli ma&#39;lumotni to&#39;g&#39;ri qidirish va ishonchliligini baholash.</li><li><strong>Aloqa va hamkorlik:</strong> Tarmoqda boshqalar bilan odobli va samarali muloqot qilish.</li><li><strong>Raqamli kontent yaratish:</strong> Matn, rasm, taqdimot va dasturiy loyihalarni mustaqil tuza olish.</li><li><strong>Kiberxavfsizlik va shaxsiy gigiyena:</strong> O&#39;z hisoblarini, parollarini va qurilmalarini himoya qilish.</li></ol><h3 id="_2-2-raqamli-madaniyat-va-netiket-tarmoq-odobi" tabindex="-1">2.2. Raqamli madaniyat va Netiket (Tarmoq odobi) <a class="header-anchor" href="#_2-2-raqamli-madaniyat-va-netiket-tarmoq-odobi" aria-label="Permalink to &quot;2.2. Raqamli madaniyat va Netiket (Tarmoq odobi)&quot;">​</a></h3><p>Real hayotda odob-axloq qoidalari bo&#39;lgani kabi, internetda ham <strong>Netiket (Network + Etiquette / Tarmoq odobi)</strong> qoidalari mavjud:</p><ul><li><strong>CapsLock bilan yozmang:</strong> KATTA HARFLAR BILAN YOZISH tarmoqda baqirish, janjallashish yoki agressiya sifatida qabul qilinadi.</li><li><strong>Boshqalarning vaqtini tejang:</strong> Salomlashib bo&#39;lgach, «mumkinmi?» deb kutmasdan, birdaniga maqsadni aniq va tushunarli yozing («Bir xabarda bitta fikr»).</li><li><strong>Kiberbulling (Cyberbullying)ga yo&#39;l qo&#39;ymang:</strong> Tarmoqda birovni haqorat qilish, masxara qilish yoki uning ruxsatisiz shaxsiy ma&#39;lumotlarini tarqatish qonunan javobgarlikka sabab bo&#39;ladi.</li><li><strong>Mualliflik huquqini hurmat qiling:</strong> Birovning maqolasi yoki rasmidan foydalanganda, albatta manzil va muallif ismini ko&#39;rsating.</li></ul><h3 id="_2-3-raqamli-iz-digital-footprint-nima" tabindex="-1">2.3. Raqamli iz (Digital Footprint) nima? <a class="header-anchor" href="#_2-3-raqamli-iz-digital-footprint-nima" aria-label="Permalink to &quot;2.3. Raqamli iz (Digital Footprint) nima?&quot;">​</a></h3><p><strong>Raqamli iz</strong> — bu siz internetdan foydalanganingizda orqangizda qoladigan barcha raqamli izlar, yozuvlar va harakatlar tarixidir. Raqamli iz 2 turga bo&#39;linadi:</p><ol><li><strong>Faol raqamli iz (Active Footprint):</strong> Siz o&#39;zingiz ongli ravishda internetga joylagan narsalar: ijtimoiy tarmoqlardagi postlar, fotosuratlar, qoldirilgan izohlar, yuborilgan xatlar.</li><li><strong>Nofaol raqamli iz (Passive Footprint):</strong> Siz sezmagan holda tizimlar tomonidan yozib olinadigan izlar: kirilgan saytlar, qidiruv tarixi, IP-manzilingiz, qaysi reklamalarni ko&#39;rganingiz.</li></ol><p><em>«Internet hech narsani unutmaydi!»</em> — bugun ijtimoiy tarmoqqa qoldirilgan noo&#39;rin fotosurat yoki izoh 10 yildan keyin nufuzli universitetga yoki nufuzli IT kompaniyasiga ishga kirishda qattiq pand berishi mumkin.</p><h3 id="_2-4-feyk-soxta-axborotlarni-aniqlash-faktcheking-qoidalari" tabindex="-1">2.4. Feyk (soxta) axborotlarni aniqlash: Faktcheking qoidalari <a class="header-anchor" href="#_2-4-feyk-soxta-axborotlarni-aniqlash-faktcheking-qoidalari" aria-label="Permalink to &quot;2.4. Feyk (soxta) axborotlarni aniqlash: Faktcheking qoidalari&quot;">​</a></h3><p>Har kuni internetda millionlab yolg&#39;on, vahimali yoki firibgarlik xabarlari tarqaladi. Ishonchli axborotni aniqlashning 5 ta oltin qoidasi:</p><ol><li><strong>Manbani tekshiring:</strong> Xabar qaysi saytda chiqdi? Rasmiy davlat saytimi (<code>.gov.uz</code>, <code>.edu.uz</code>) yoki noma&#39;lum Telegram kanalmi?</li><li><strong>Muallif kimligini aniqlang:</strong> Xabarni kim yozgan? Soha mutaxassisimi yoki anonim profilmi?</li><li><strong>Boshqa manbalar bilan solishtiring:</strong> Ushbu yangilikni nufuzli rasmiy axborot agentliklari (Daryo, Kun.uz, O&#39;zA) e&#39;lon qildimi? Agar faqat bitta kanalda bo&#39;lsa — bu 90% feyk.</li><li><strong>Sana va kontekstga qarang:</strong> Ko&#39;pincha 5 yil oldingi eski video yoki falokat yangi xabar qilib tarqatiladi.</li><li><strong>Hissiyotga berilmang:</strong> «Shoshilinch! Hamma ko&#39;rsin! Barcha guruhlarga tarqating!» kabi vahimali jumlalar — klassik feyk va klikbeyt belgisidir.</li></ol><hr>',15))]),i("div",u,[i("h2",b,[o(t,{name:"file-text"}),a[6]||(a[6]=l(" 3. Amaliy topshiriqlar va yechimlari ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-amaliy-topshiriqlar-va-yechimlari","aria-label":'Permalink to "<Icon name="file-text" /> 3. Amaliy topshiriqlar va yechimlari"'},"​",-1))]),a[8]||(a[8]=n('<h3 id="_1-topshiriq-shaxsiy-raqamli-iz-auditi" tabindex="-1">1-topshiriq. Shaxsiy raqamli iz auditi <a class="header-anchor" href="#_1-topshiriq-shaxsiy-raqamli-iz-auditi" aria-label="Permalink to &quot;1-topshiriq. Shaxsiy raqamli iz auditi&quot;">​</a></h3><p><strong>Vazifa:</strong> Google qidiruviga o&#39;z ism-familiyangizni qo&#39;shtirnoq ichida (<code>&quot;Ism Familiya&quot;</code>) yozib qidiring. Siz haqingizda internetda qanday ma&#39;lumotlar, qaysi saytlarda chiqib kelganini tahlil qiling. <strong>Yechim:</strong></p><ul><li>O&#39;quvchi qidiruvga masalan: <code>&quot;Sherzod Alimov Toshkent&quot;</code> deb yozadi.</li><li>Chiqqan maktab olimpiadasi ro&#39;yxati, sport musobaqalari yoki ijtimoiy tarmoq profillarini ko&#39;rib chiqib, o&#39;zining raqamli izinga baho beradi.</li></ul><h3 id="_2-topshiriq-feyk-yangilikni-tahlil-qilish-keys-tahlili" tabindex="-1">2-topshiriq. Feyk yangilikni tahlil qilish (Keys tahlili) <a class="header-anchor" href="#_2-topshiriq-feyk-yangilikni-tahlil-qilish-keys-tahlili" aria-label="Permalink to &quot;2-topshiriq. Feyk yangilikni tahlil qilish (Keys tahlili)&quot;">​</a></h3><p><strong>Vazifa:</strong> Quyidagi xabarni tahlil qiling: «Diqqat! Ertadan boshlab barcha maktablarda darslar 6 kunga uzaytiriladi va telefonlar musodara qilinadi! Bu xabarni 10 ta guruhga tarqatmasangiz, profilingiz bloklanadi!» Feyk ekanligining 3 ta isbotini keltiring. <strong>Yechim:</strong></p><ol><li>Rasmiy manba yoki vazirlik hujjati yo&#39;q (anonim xabar).</li><li>Asossiz vahima va qo&#39;rqitish («profilingiz bloklanadi»).</li><li>«10 ta guruhga tarqating» degan klassik spam/virusli tarqatish zanjiri bor.</li></ol><hr>',7))]),i("div",y,[i("h2",v,[o(t,{name:"file-text"}),a[9]||(a[9]=l(" 4. Tezkor nazorat savollari (javoblari bilan) ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#_4-tezkor-nazorat-savollari-javoblari-bilan","aria-label":'Permalink to "<Icon name="file-text" /> 4. Tezkor nazorat savollari (javoblari bilan)"'},"​",-1))]),a[11]||(a[11]=n("<ol><li><strong>Savol:</strong> Nima uchun internetda CapsLock (katta harflar) bilan yozish odobsizlik hisoblanadi? <strong>Javob:</strong> Chunki internet muloqotida katta harflar bilan yozish baqirish, agressiya va hurmatsizlik sifatida talqin qilinadi.</li><li><strong>Savol:</strong> Faol va nofaol raqamli iz o&#39;rtasidagi farq nimada? <strong>Javob:</strong> Faol raqamli iz — o&#39;zimiz ongli joylagan postlar va fotosuratlar; nofaol raqamli iz — biz bilmagan holda saqlanadigan saytlar tarixi, IP manzil va kukilardir.</li><li><strong>Savol:</strong> «Internet hech narsani unutmaydi» iborasi nimani anglatadi? <strong>Javob:</strong> Internetga bir marta yuklangan ma&#39;lumot boshqalar tomonidan skrinshot qilib olinishi yoki keshda saqlanib qolishi mumkin, uni butunlay yo&#39;q qilib bo&#39;lmaydi.</li><li><strong>Savol:</strong> Faktcheking nima? <strong>Javob:</strong> Internetdagi yangiliklar, faktlar va xabarlarning to&#39;g&#39;riligini rasmiy manbalar orqali tekshirish jarayoni.</li><li><strong>Savol:</strong> Kiberbullingga uchragan o&#39;quvchi qanday yo&#39;l tutishi kerak? <strong>Javob:</strong> Haqoratga javob bermaslik, tajovuzkorni bloklash, xabarlarni skrinshot qilib ota-onasi yoki o&#39;qituvchisiga xabar berish kerak.</li></ol>",1))])])}const I=r(m,[["render",f]]);export{j as __pageData,I as default};
